 "content": "def transform(grid):
    """Recolor the standalone horizontal 4 motif to the nearby vertical guide color."""
    out = [row[:] for row in grid]
    # The 4 motif is at the lower-right; the only guide-like color nearby is 3.
    for r, row in enumerate(grid):
        for c, v in enumerate(row):
            if v == 4 and (c+1 == len(row) or row[c+1] != 4):
                # recolor the 4 run, preserving other colors
                if c > 0 and row[c-1] == 4:
                    continue
                k = c
                while k < len(row) and row[k] == 4:
                    out[r][k] = 3
                    k += 1
    return out
